// Step gates and restoring the module's state from saved records (pure; no DOM).
// Order of discovery: an ozone prediction unlocks Compare for that hour and setting and opens
// Explore; reaching Compare for at least one setting opens the NO2 extension; the NO2 result
// is shown only after an NO2 prediction has been recorded.
import type { LinearityRecord } from "../types";

export interface RestoredPrediction { tracer: number; o3: number; expect: string; why: string; usedSum: boolean }

export interface RestoredPin { scenario: string; base: { nox: number; voc: number }; addA: { nox: number; voc: number }; addB: { nox: number; voc: number } }

export interface RestoredState {
  preds: Map<string, RestoredPrediction>;   // key `${scenario}|${setting}`
  compared: Set<string>;
  no2: { choice: string; factor: string; revealed: boolean };
  notes: Map<string, string>;               // latest saved note per `${scenario}|${setting}`
  pins: RestoredPin[];                      // marked points in step 5, in order (removals applied)
}

const mix = (v: unknown): { nox: number; voc: number } | null => {
  const m = v as Record<string, unknown> | null | undefined;
  const nox = Number(m?.nox), voc = Number(m?.voc);
  return m && Number.isFinite(nox) && Number.isFinite(voc) ? { nox, voc } : null;
};

export interface GateInput {
  predictedHere: boolean;   // a prediction exists for the current hour and setting
  anyPrediction: boolean;
  anyCompared: boolean;     // Compare (step 4) reached for at least one hour and setting
}

export type LockReason = "predict-first" | "compare-first" | null;

/** Why step n is locked, or null when it is open. */
export function stepLock(n: number, g: GateInput): LockReason {
  if (n === 4 && !g.predictedHere) return "predict-first";
  if (n === 5 && !g.anyPrediction) return "predict-first";
  if (n === 6 && !g.anyCompared) return "compare-first";
  return null;
}

/** The NO2 result may be shown only after an NO2 prediction and with the step open. */
export function no2CanReveal(choice: string, g: GateInput): boolean {
  return g.anyCompared && choice !== "";
}

/** Rebuild predictions, compared settings and the NO2 state from saved records (in order). */
export function restoreFromRecords(records: readonly LinearityRecord[] | undefined): RestoredState {
  const out: RestoredState = { preds: new Map(), compared: new Set(), no2: { choice: "", factor: "", revealed: false }, notes: new Map(), pins: [] };
  for (const r of records ?? []) {
    if (!r || typeof r.step !== "string") continue;
    const p = r.prediction as Record<string, unknown> | undefined;
    const o = r.observed as Record<string, unknown> | undefined;
    if (r.step === "predict" && p && typeof p.scenario === "string" && typeof p.setting === "string") {
      const tracer = Number(p.tracer_nox_ppb);
      const o3 = Number(p.o3_change_ppb);
      if (!Number.isFinite(tracer) || !Number.isFinite(o3)) continue;
      out.preds.set(`${p.scenario}|${p.setting}`, {
        tracer, o3, expect: String(p.expectation ?? ""), why: String(p.reason ?? ""), usedSum: !!p.used_sum_button,
      });
    } else if (r.step === "compare" && o && typeof o.scenario === "string" && typeof o.setting === "string") {
      // A compare entry counts only when a prediction for that hour and setting came first.
      const k = `${o.scenario}|${o.setting}`;
      if (out.preds.has(k)) out.compared.add(k);
    } else if (r.step === "no2-predict" && p && typeof p.choice === "string" && p.choice !== "") {
      out.no2.choice = p.choice;
      out.no2.factor = p.factor === null || p.factor === undefined ? "" : String(p.factor);
    } else if (r.step === "note" && o && typeof o.scenario === "string" && typeof o.setting === "string" && typeof o.text === "string") {
      out.notes.set(`${o.scenario}|${o.setting}`, o.text);
    } else if (r.step === "explore-pin" && o && typeof o.scenario === "string") {
      const base = mix({ nox: o.nox_ppb, voc: o.voc_ppbC }), addA = mix(o.add_a), addB = mix(o.add_b);
      if (base && addA && addB) out.pins.push({ scenario: o.scenario, base, addA, addB });
    } else if (r.step === "explore-unpin" && o && Number.isInteger(o.index)) {
      out.pins.splice(o.index as number, 1);
    } else if (r.step === "no2-reveal") {
      // Shown again only if an NO2 prediction was recorded before it and step 6 was open.
      if (out.no2.choice !== "" && out.compared.size > 0) out.no2.revealed = true;
    }
  }
  return out;
}
