// Ozone response table: types, bilinear lookup, source combinations and contour lines.
// Pure functions with no DOM access, so they can be unit-tested in node (table.test.ts).
// The rules mirror aqsim/ozone/validate.py `bilinear` (clamp to the axes, then bilinear).

export interface OzoneSetting {
  label: string;
  description: string;
  voc_ppbC: number;
  nox_ppb: number;
}

export interface OzoneSource {
  label: string;
  emits: string;
  catalogue_id: string;
  add_nox_ppb: number;
  add_voc_ppbC: number;
  offset_upwind_m: number;
  offset_crosswind_m?: number;
}

export interface OzoneScenarioTable {
  label: string;
  date: string;
  hour_ending_lst: number;
  kind: "day" | "dark" | string;
  quantity: string;
  description: string;
  window_lst: number[];
  o3_background_ppb: number;
  o3_background_source: string;
  o3_ppb: number[][];          // [i][j]: i over axes.nox_ppb, j over axes.voc_ppbC
}

export interface OzoneTableData {
  format: string;
  format_version: number;
  units: Record<string, string>;
  layout: string;
  axes: { nox_ppb: number[]; voc_ppbC: number[] };
  module: {
    default_scenario: string;
    settings: Record<string, OzoneSetting>;
    sources: Record<string, OzoneSource>;
    nox_ug_m3_per_ppb: number;
    voc_ug_m3_per_ppbC: number;
    monitor_m?: { x: number; y: number };
  };
  conversions: Record<string, number>;
  content_sha256: string;
  scenarios: Record<string, OzoneScenarioTable>;
}

export interface Lookup {
  value: number;
  clamped: boolean;            // true when the point lies outside the table and was moved onto its edge
}

/** Index i with axis[i] <= q < axis[i+1] (clipped to the last interval) and the weight in it. */
export function bracket(axis: number[], q: number): { i: number; w: number } {
  const n = axis.length;
  if (n < 2) throw new Error("axis needs at least two nodes");
  let lo = 0;
  let hi = n - 1;
  if (q <= axis[0]) return { i: 0, w: 0 };
  if (q >= axis[n - 1]) return { i: n - 2, w: 1 };
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (axis[mid] <= q) lo = mid;
    else hi = mid;
  }
  return { i: lo, w: (q - axis[lo]) / (axis[lo + 1] - axis[lo]) };
}

/** Bilinear O3 (ppb) at (NOx ppb, VOC ppbC); points outside the axes are clamped and flagged. */
export function lookup(data: OzoneTableData, scenarioId: string, nox: number, voc: number): Lookup {
  const sc = data.scenarios[scenarioId];
  if (!sc) throw new Error(`no ozone table for scenario ${scenarioId}`);
  const nx = data.axes.nox_ppb;
  const vx = data.axes.voc_ppbC;
  const clamped = nox < nx[0] || nox > nx[nx.length - 1] || voc < vx[0] || voc > vx[vx.length - 1];
  const a = bracket(nx, nox);
  const b = bracket(vx, voc);
  const t = sc.o3_ppb;
  const v =
    (1 - a.w) * (1 - b.w) * t[a.i][b.i] +
    a.w * (1 - b.w) * t[a.i + 1][b.i] +
    (1 - a.w) * b.w * t[a.i][b.i + 1] +
    a.w * b.w * t[a.i + 1][b.i + 1];
  return { value: v, clamped };
}

export interface Mixture {
  nox: number;   // ppb
  voc: number;   // ppbC
}

export interface Addition {
  nox: number;
  voc: number;
}

export interface Combination {
  base: number;          // O3 without either source (ppb)
  a: number;             // change with A alone
  b: number;             // change with B alone
  sum: number;           // a + b (the sandbox's method)
  both: number;          // change with A and B together (chemistry table)
  interaction: number;   // both - sum
  clamped: boolean;
  points: { base: Mixture; a: Mixture; b: Mixture; both: Mixture };
}

/** Changes in O3 at the monitor for A alone, B alone, their sum and both together. */
export function combine(data: OzoneTableData, scenarioId: string, base: Mixture, addA: Addition, addB: Addition): Combination {
  const pts = {
    base,
    a: { nox: base.nox + addA.nox, voc: base.voc + addA.voc },
    b: { nox: base.nox + addB.nox, voc: base.voc + addB.voc },
    both: { nox: base.nox + addA.nox + addB.nox, voc: base.voc + addA.voc + addB.voc },
  };
  const L0 = lookup(data, scenarioId, pts.base.nox, pts.base.voc);
  const LA = lookup(data, scenarioId, pts.a.nox, pts.a.voc);
  const LB = lookup(data, scenarioId, pts.b.nox, pts.b.voc);
  const LAB = lookup(data, scenarioId, pts.both.nox, pts.both.voc);
  const a = LA.value - L0.value;
  const b = LB.value - L0.value;
  const both = LAB.value - L0.value;
  return {
    base: L0.value, a, b, sum: a + b, both, interaction: both - (a + b),
    clamped: L0.clamped || LA.clamped || LB.clamped || LAB.clamped, points: pts,
  };
}

/** Scale an addition (a source's emission rate multiplied by m changes its increment by m). */
export function scaled(add: Addition, m: number): Addition {
  return { nox: add.nox * m, voc: add.voc * m };
}

/** Sample the bilinear surface on a regular grid (for contouring and colour maps). */
export function sampleGrid(data: OzoneTableData, scenarioId: string, vocMax: number, noxMax: number, nv: number, nn: number): number[][] {
  const g: number[][] = [];
  for (let r = 0; r <= nn; r++) {
    const row: number[] = [];
    for (let c = 0; c <= nv; c++) row.push(lookup(data, scenarioId, (r / nn) * noxMax, (c / nv) * vocMax).value);
    g.push(row);
  }
  return g;
}

export type Segment = [number, number, number, number];   // x1, y1, x2, y2 in grid units (column, row)

/** Marching squares: line segments of one contour level through a regular grid g[row][col]. */
export function contourSegments(g: number[][], level: number): Segment[] {
  const out: Segment[] = [];
  for (let r = 0; r < g.length - 1; r++) {
    for (let c = 0; c < g[r].length - 1; c++) {
      const v = [g[r][c], g[r][c + 1], g[r + 1][c + 1], g[r + 1][c]];
      const P: [number, number][] = [[c, r], [c + 1, r], [c + 1, r + 1], [c, r + 1]];
      const pts: [number, number][] = [];
      for (let e = 0; e < 4; e++) {
        const a = v[e];
        const b = v[(e + 1) % 4];
        if ((a < level) !== (b < level)) {
          const t = (level - a) / (b - a);
          const p0 = P[e];
          const p1 = P[(e + 1) % 4];
          pts.push([p0[0] + t * (p1[0] - p0[0]), p0[1] + t * (p1[1] - p0[1])]);
        }
      }
      if (pts.length === 2) out.push([pts[0][0], pts[0][1], pts[1][0], pts[1][1]]);
      else if (pts.length === 4) {
        // Saddle: pair the crossings by the cell-centre value.
        const centre = (v[0] + v[1] + v[2] + v[3]) / 4;
        if ((centre < level) === (v[0] < level)) {
          out.push([pts[0][0], pts[0][1], pts[3][0], pts[3][1]], [pts[1][0], pts[1][1], pts[2][0], pts[2][1]]);
        } else {
          out.push([pts[0][0], pts[0][1], pts[1][0], pts[1][1]], [pts[2][0], pts[2][1], pts[3][0], pts[3][1]]);
        }
      }
    }
  }
  return out;
}

/** For each VOC level (grid column), the NOx (ppb) where O3 is highest. */
export function ridgeLine(data: OzoneTableData, scenarioId: string): Mixture[] {
  const sc = data.scenarios[scenarioId];
  const out: Mixture[] = [];
  data.axes.voc_ppbC.forEach((voc, j) => {
    let best = 0;
    for (let i = 1; i < data.axes.nox_ppb.length; i++) if (sc.o3_ppb[i][j] > sc.o3_ppb[best][j]) best = i;
    if (best > 0) out.push({ nox: data.axes.nox_ppb[best], voc });
  });
  return out;
}

/** Engine rate (g/s) that gives a target tracer increment at the monitor, from a unit-rate value. */
export function rateForIncrement(targetUgM3: number, unitUgM3PerGs: number): number | null {
  if (!(targetUgM3 > 0)) return 0;
  if (!(unitUgM3PerGs > 0) || !Number.isFinite(unitUgM3PerGs)) return null;
  return targetUgM3 / unitUgM3PerGs;
}

/** Source position: `upwind` metres toward the wind's origin, `crosswind` to its right. */
export function upwindPosition(monitorX: number, monitorY: number, windFromDeg: number, upwind: number, crosswind = 0): { x: number; y: number } {
  const th = (windFromDeg * Math.PI) / 180;
  const ux = Math.sin(th);
  const uy = Math.cos(th);
  // Unit vector pointing to the right of an observer facing the wind's origin.
  const rx = uy;
  const ry = -ux;
  return { x: monitorX + upwind * ux + crosswind * rx, y: monitorY + upwind * uy + crosswind * ry };
}

/** Signed number with a fixed number of decimals and a true minus sign. */
export function signed(v: number, digits = 1): string {
  const r = Number(v.toFixed(digits));
  if (r === 0) return (0).toFixed(digits);
  return (r > 0 ? "+" : "−") + Math.abs(r).toFixed(digits);
}
