// Linearity edge module (Agent G). Contract: docs/phase3_interfaces.md, "Linearity module mount".
// Self-contained: touches no DOM outside `root`, imports only types from ../types, and carries
// its ozone table as a generated module (canonical copy: export/ozone/ozone_tables.json).
import type { LinearityContext, LinearityRecord, Placement } from "../types";
import { OZONE_TABLE } from "./ozoneTable.generated";
import { STYLES } from "./styles";
import {
  combine as combineRaw, contourSegments, lookup, rateForIncrement, ridgeLine, sampleGrid, scaled, signed, upwindPosition,
  type Addition, type Combination, type Mixture, type OzoneTableData,
} from "./table";
import { T } from "./text";
import { no2CanReveal, restoreFromRecords, stepLock, type GateInput } from "./gates";

export type { OzoneTableData } from "./table";

/** Optional extension of the context: a different ozone table (for example a newer export). */
export interface LinearityContextG extends LinearityContext {
  ozoneTable?: OzoneTableData;
}

/** Warning text for the sandbox when its linear engine is applied to a secondary pollutant. */
export function linearEngineWarning(pollutant: string, opts: { no2Chemistry?: boolean } = {}): { title: string; text: string } | null {
  if (pollutant === "O3") return { title: T.warnO3Title, text: T.warnO3Text };
  if (pollutant === "NO2" && opts.no2Chemistry) return { title: T.warnNo2Title, text: T.warnNo2Text };
  return null;
}

type SettingKey = string;
interface Prediction { tracer: number; o3: number; expect: string; why: string; usedSum: boolean }
interface TracerResult {
  status: "loading" | "ok" | "unavailable";
  nox: { a: number; b: number; both: number };     // ppb
  voc: { a: number; b: number; both: number };     // ppbC
  rates: { a: [number, number] | null; b: [number, number] | null };  // [NOx, VOC] g/s
  far: boolean;
}
interface Pin { scenario: string; base: Mixture; addA: Addition; addB: Addition; c: Combination }

/** The table's combination, with the sum taken over the displayed (1-decimal) parts so the shown numbers add up. */
const r1 = (v: number) => Math.round(v * 10) / 10;
function combine(...args: Parameters<typeof combineRaw>): Combination {
  const c = combineRaw(...args), sum = r1(c.a) + r1(c.b);
  return { ...c, sum, interaction: r1(c.both) - sum };
}

const NOX_MAX = 160;
const VOC_MAX = 1200;

export function mountLinearity(root: HTMLElement, ctx: LinearityContext): () => void {
  const data: OzoneTableData = (ctx as LinearityContextG).ozoneTable ?? OZONE_TABLE;
  const mod = data.module;
  const settingKeys = Object.keys(mod.settings);
  const A = mod.sources.A;
  const B = mod.sources.B;
  const scenarioIds = ctx.scenarioIds.filter((id) => id in data.scenarios);
  const hourLabel = (id: string) => {
    try { return ctx.getScenario(id).label; } catch { return data.scenarios[id]?.label ?? id; }
  };

  const S = {
    step: 1,
    scenario: scenarioIds.includes(mod.default_scenario) ? mod.default_scenario : scenarioIds[0],
    setting: settingKeys[0] as SettingKey,
    preds: new Map<string, Prediction>(),
    compared: new Set<string>(),
    draft: { tracer: "", o3: "", expect: "", why: "", usedSum: false },
    editing: false,
    notes: new Map<string, string>(),   // step 4 note per `${scenario}|${setting}`
    ex: { base: null as Mixture | null, addANox: A.add_nox_ppb, addBVoc: B.add_voc_ppbC, mult: 1, ridge: false, pins: [] as Pin[] },
    no2: { choice: "", factor: "", revealed: false },
    tracer: new Map<string, TracerResult>(),
  };
  const key = () => `${S.scenario}|${S.setting}`;
  const now = () => Date.now();
  const rec = (e: Omit<LinearityRecord, "t">) => { try { ctx.record({ ...e, t: now() }); } catch { /* host problem; keep going */ } };

  // ---- restore from saved records (optional extension); gates are re-derived, never trusted
  {
    const R = restoreFromRecords(ctx.records);
    S.preds = R.preds;
    S.compared = R.compared;
    S.no2 = R.no2;
    S.notes = R.notes;
    S.ex.pins = R.pins.filter((p) => data.scenarios[p.scenario]).map((p) => ({ ...p, c: combine(data, p.scenario, p.base, p.addA, p.addB) }));
  }

  // ---- DOM skeleton (everything lives inside root)
  root.innerHTML = "";
  const host = el("div", "glin");
  const style = document.createElement("style");
  style.textContent = STYLES;
  host.append(style);
  host.insertAdjacentHTML("beforeend", `
    <h2 class="glin-title">${T.title}</h2>
    <nav class="glin-steps" aria-label="Steps"><ol></ol></nav>
    <div class="glin-grid">
      <section class="glin-main" aria-live="polite"></section>
      <aside class="glin-side">
        <figure class="glin-fig">
          <canvas class="glin-canvas" tabindex="0" role="img"></canvas>
          <figcaption class="glin-hint"></figcaption>
        </figure>
        <div class="glin-placeholder">${esc("The ozone diagram appears after you record a prediction.")}</div>
      </aside>
    </div>
    <div class="glin-instructor"></div>`);
  root.append(host);
  const stepsOl = host.querySelector(".glin-steps ol") as HTMLOListElement;
  const main = host.querySelector(".glin-main") as HTMLElement;
  const canvas = host.querySelector("canvas") as HTMLCanvasElement;
  const fig = host.querySelector(".glin-fig") as HTMLElement;
  const placeholder = host.querySelector(".glin-placeholder") as HTMLElement;
  const hint = host.querySelector(".glin-hint") as HTMLElement;
  const instr = host.querySelector(".glin-instructor") as HTMLElement;

  // ---- derived values
  const settingMix = (k = S.setting): Mixture => ({ nox: mod.settings[k].nox_ppb, voc: mod.settings[k].voc_ppbC });
  const addOf = (src: typeof A): Addition => ({ nox: src.add_nox_ppb, voc: src.add_voc_ppbC });
  const fixedCombo = (sid = S.scenario, k = S.setting) => combine(data, sid, settingMix(k), addOf(A), addOf(B));
  const exAddA = (): Addition => ({ nox: S.ex.addANox, voc: A.add_nox_ppb > 0 ? (A.add_voc_ppbC * S.ex.addANox) / A.add_nox_ppb : A.add_voc_ppbC });
  const exAddB = (): Addition => ({ nox: B.add_voc_ppbC > 0 ? (B.add_nox_ppb * S.ex.addBVoc) / B.add_voc_ppbC : B.add_nox_ppb, voc: S.ex.addBVoc });
  const exBase = (): Mixture => S.ex.base ?? settingMix();
  const isDay = (sid = S.scenario) => data.scenarios[sid].kind === "day";
  const unlocked = () => S.preds.has(key());          // compare needs a prediction for this hour and setting
  const gate = (): GateInput => ({ predictedHere: unlocked(), anyPrediction: S.preds.size > 0, anyCompared: S.compared.size > 0 });
  const lockText = (n: number) => { const r = stepLock(n, gate()); return r === "predict-first" ? T.lockedStep : r === "compare-first" ? T.lockedNo2 : ""; };

  // ---- tracer via the sandbox engine
  function tracerFor(sid: string): TracerResult {
    const cached = S.tracer.get(sid);
    if (cached) return cached;
    const fallback: TracerResult = {
      status: "loading", nox: { a: A.add_nox_ppb, b: B.add_nox_ppb, both: NaN }, voc: { a: A.add_voc_ppbC, b: B.add_voc_ppbC, both: NaN },
      rates: { a: null, b: null }, far: false,
    };
    S.tracer.set(sid, fallback);
    const pre = ctx.engine.preload ? ctx.engine.preload([A.catalogue_id, B.catalogue_id], sid) : Promise.resolve();
    pre.then(() => computeTracer(sid)).catch(() => { fallback.status = "unavailable"; }).finally(() => {
      if (S.scenario === sid && (S.step === 2 || S.step === 4)) render();
    });
    return fallback;
  }

  function computeTracer(sid: string) {
    const r = S.tracer.get(sid)!;
    const meta = ctx.getScenario(sid);
    const mon = mod.monitor_m ?? { x: 486000, y: 4422000 };
    const pa = upwindPosition(mon.x, mon.y, meta.wd_deg, A.offset_upwind_m, A.offset_crosswind_m ?? 0);
    const pb = upwindPosition(mon.x, mon.y, meta.wd_deg, B.offset_upwind_m, B.offset_crosswind_m ?? 0);
    const xq = new Float64Array([mon.x]);
    const yq = new Float64Array([mon.y]);
    const zq = new Float64Array([0]);
    const at = (pl: Placement[]) => ctx.engine.superpose(pl, sid, xq, yq, zq)[0];
    const pA = (rate: number): Placement => ({ source_id: A.catalogue_id, x: pa.x, y: pa.y, rate_g_s: rate });
    const pB = (rate: number): Placement => ({ source_id: B.catalogue_id, x: pb.x, y: pb.y, rate_g_s: rate });
    const unitA = at([pA(1)]);
    const unitB = at([pB(1)]);
    const fN = mod.nox_ug_m3_per_ppb;
    const fV = mod.voc_ug_m3_per_ppbC;
    const rAn = rateForIncrement(A.add_nox_ppb * fN, unitA);
    const rAv = rateForIncrement(A.add_voc_ppbC * fV, unitA);
    const rBn = rateForIncrement(B.add_nox_ppb * fN, unitB);
    const rBv = rateForIncrement(B.add_voc_ppbC * fV, unitB);
    if (rAn === null || rAv === null || rBn === null || rBv === null) { r.status = "unavailable"; return; }
    const placementsNox = [pA(rAn), pB(rBn)];
    const placementsVoc = [pA(rAv), pB(rBv)];
    r.nox = { a: at([placementsNox[0]]) / fN, b: at([placementsNox[1]]) / fN, both: at(placementsNox) / fN };
    r.voc = { a: at([placementsVoc[0]]) / fV, b: at([placementsVoc[1]]) / fV, both: at(placementsVoc) / fV };
    r.rates = { a: [rAn, rAv], b: [rBn, rBv] };
    r.far = Math.max(rAn, rAv, rBn, rBv) > 2000;
    r.status = "ok";
  }

  // ---- stepper
  function renderSteps() {
    stepsOl.innerHTML = "";
    T.steps.forEach((name, i) => {
      const n = i + 1;
      const li = document.createElement("li");
      const b = document.createElement("button");
      b.type = "button";
      b.textContent = `${n} ${name}`;
      const why = lockText(n);
      b.disabled = why !== "";
      if (why) b.title = why;
      if (n === S.step) { b.setAttribute("aria-current", "step"); li.className = "on"; }
      else if (n < S.step) li.className = "done";
      b.onclick = () => go(n);
      li.append(b);
      stepsOl.append(li);
    });
  }

  function go(n: number) {
    if (lockText(n)) return;
    S.step = n;
    render();
    (main.querySelector("h3") as HTMLElement | null)?.focus();
  }

  function nav(prev: number | null, next: number | null, nextLabel: string = T.nav.next, disabled = false): string {
    return `<div class="glin-nav">${prev ? `<button type="button" class="glin-btn" data-go="${prev}">${T.nav.back}</button>` : ""}${
      next ? `<button type="button" class="glin-btn primary" data-go="${next}" ${disabled ? "disabled" : ""}>${esc(nextLabel)}</button>` : ""}</div>`;
  }

  const warnO3 = () => `<div class="glin-warn" role="note"><b>${T.warnO3Title}.</b> <span>${T.warnO3Text}</span></div>`;
  const warnNo2 = () => `<div class="glin-warn" role="note"><b>${T.warnNo2Title}.</b> <span>${T.warnNo2Text}</span></div>`;

  // ---- step renderers
  function step1(): string {
    const sc = data.scenarios[S.scenario];
    return `<h3 tabindex="-1">${T.s1Heading}</h3>
      ${T.s1Intro.map((p) => `<p>${esc(p)}</p>`).join("")}
      <label class="glin-field"><span>${T.hourLabel}</span>
        <select data-k="scenario">${scenarioIds.map((id) => `<option value="${id}" ${id === S.scenario ? "selected" : ""}>${esc(hourLabel(id))} (${data.scenarios[id].kind === "day" ? T.hourDay : T.hourDark})</option>`).join("")}</select></label>
      <p class="glin-hint">${esc(sc.kind === "day" ? T.hourDayLong(sc.date) : T.hourDarkLong(sc.date, sc.hour_ending_lst))} ${esc(T.backgroundO3(sc.o3_background_ppb))}</p>
      <fieldset class="glin-choice"><legend>${T.settingLabel}</legend>
        ${settingKeys.map((k) => { const st = mod.settings[k]; return `<label class="${k === S.setting ? "on" : ""}"><input type="radio" name="glin-setting" value="${k}" ${k === S.setting ? "checked" : ""}>
          <b>${esc(st.label)}</b><br><span class="glin-hint">${esc(st.description)} ${esc(T.mixture(st.voc_ppbC, st.nox_ppb))}</span></label>`; }).join("")}
      </fieldset>
      <div class="glin-cards">${[A, B].map((s) => `<div class="glin-card"><div class="lbl">${esc(s.label)}</div><div>${esc(T.sourceAdds(s.emits, s.add_nox_ppb, s.add_voc_ppbC))}</div></div>`).join("")}</div>
      <details class="glin-details"><summary>${T.modelSummary}</summary>${T.modelText.map((p) => `<p>${esc(p)}</p>`).join("")}</details>
      ${nav(null, 2)}`;
  }

  function tracerTable(tr: TracerResult): string {
    if (tr.status === "loading") return `<p class="glin-hint">${T.engineLoading}</p>`;
    const un = tr.status === "unavailable" ? `<p class="glin-hint">${T.engineUnavailable}</p>` : "";
    const fmtRate = (r: [number, number] | null) => r ? `${r[0].toPrecision(3)} g/s NOx, ${r[1].toPrecision(3)} g/s VOC` : "—";
    return `${un}<table class="glin-table"><thead><tr><th></th><th>${T.colA}</th><th>${T.colB}</th></tr></thead><tbody>
      <tr><th>${T.tracerRow.nox}</th><td>${signed(tr.nox.a)} ppb</td><td>${signed(tr.nox.b)} ppb</td></tr>
      <tr><th>${T.tracerRow.voc}</th><td>${signed(tr.voc.a, 0)} ppbC</td><td>${signed(tr.voc.b, 0)} ppbC</td></tr></tbody></table>
      ${tr.status === "ok" ? `<p class="glin-hint">${esc(T.rateNote(fmtRate(tr.rates.a), fmtRate(tr.rates.b)))}${tr.far ? " " + esc(T.rateFar) : ""}</p>` : ""}`;
  }

  function step2(): string {
    const c = fixedCombo();
    const tr = tracerFor(S.scenario);
    const q = isDay() ? "peak 1-hour ozone, 08–18 LST" : "ozone after one hour without sunlight";
    return `<h3 tabindex="-1">${T.s2Heading}</h3>
      <p class="glin-hint">${esc(mod.settings[S.setting].label)} · ${esc(hourLabel(S.scenario))}</p>
      <h4>${T.s2TracerHeading}</h4>
      ${tracerTable(tr)}
      <p class="glin-hint">${T.s2TracerNote}</p>
      <h4>${T.s2O3Heading} <span class="glin-hint">(${q})</span></h4>
      <div class="glin-cards">
        <div class="glin-card"><div class="lbl">${T.s2O3None}</div><div class="val">${c.base.toFixed(1)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.s2O3A}</div><div class="val">${signed(c.a)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.s2O3B}</div><div class="val">${signed(c.b)} ppb</div></div>
      </div>
      <p class="glin-prompt">${T.s2Prompt}</p>
      ${nav(1, 3)}`;
  }

  function step3(): string {
    const c = fixedCombo();
    const p = S.preds.get(key());
    const locked = !!p && !S.editing;
    const d = locked ? { tracer: String(p!.tracer), o3: String(p!.o3), expect: p!.expect, why: p!.why } : S.draft;
    return `<h3 tabindex="-1">${T.s3Heading}</h3>
      <p class="glin-hint">${esc(mod.settings[S.setting].label)} · ${esc(hourLabel(S.scenario))}</p>
      ${warnO3()}
      <label class="glin-field"><span>${T.s3TracerLabel}</span><input type="number" step="0.1" data-k="tracer" value="${esc(d.tracer)}" ${locked ? "disabled" : ""}></label>
      <label class="glin-field"><span>${T.s3O3Label}</span><input type="number" step="0.1" data-k="o3" value="${esc(d.o3)}" ${locked ? "disabled" : ""}></label>
      ${locked ? "" : `<p><button type="button" class="glin-btn" data-act="use-sum">${esc(T.s3SumButton(signed(c.sum)))}</button></p>`}
      <fieldset class="glin-choice inline"><legend>${T.s3ExpectLabel}</legend>
        ${T.s3Expect.map(([k, t]) => `<label class="${d.expect === k ? "on" : ""}"><input type="radio" name="glin-expect" value="${k}" ${d.expect === k ? "checked" : ""} ${locked ? "disabled" : ""}> ${t}</label>`).join("")}
      </fieldset>
      <label class="glin-field"><span>${T.s3WhyLabel}</span><textarea data-k="why" rows="2" ${locked ? "disabled" : ""}></textarea></label>
      ${locked
        ? `<p class="glin-hint">${T.s3Recorded} <button type="button" class="glin-link" data-act="edit">${T.s3Change}</button></p>${nav(2, 4)}`
        : `<p class="glin-hint" data-k="need">${T.s3Need}</p>${nav(2, null)}<p><button type="button" class="glin-btn primary" data-act="record" ${draftValid() ? "" : "disabled"}>${T.s3Record}</button></p>`}`;
  }

  function draftValid() {
    return S.draft.tracer.trim() !== "" && S.draft.o3.trim() !== "" && Number.isFinite(Number(S.draft.tracer)) && Number.isFinite(Number(S.draft.o3));
  }

  function bars(rows: [string, number, string][], unit: string): string {
    const span = Math.max(1e-9, ...rows.map((r) => Math.abs(r[1]))) * 1.1;
    const hasNeg = rows.some((r) => r[1] < 0);
    const z0 = hasNeg ? 50 : 0;
    const sc = (hasNeg ? 50 : 100) / span;
    return `<div class="glin-bars">${rows.map(([t, v, cls]) => {
      const left = v >= 0 ? z0 : z0 + v * sc;
      return `<div class="row"><span class="lab">${t}</span><span class="track" aria-hidden="true"><span class="zero" style="left:${z0}%"></span><span class="fill ${cls}" style="left:${left}%;width:${Math.abs(v) * sc}%"></span></span><span class="v">${signed(v)} ${unit}</span></div>`;
    }).join("")}</div>`;
  }

  function step4(): string {
    const c = fixedCombo();
    const p = S.preds.get(key())!;
    const tr = tracerFor(S.scenario);
    const doneNames = settingKeys.filter((k) => S.compared.has(`${S.scenario}|${k}`)).map((k) => mod.settings[k].label);
    return `<h3 tabindex="-1">${T.s4Heading}</h3>
      <p class="glin-hint">${esc(mod.settings[S.setting].label)} · ${esc(hourLabel(S.scenario))}</p>
      <h4>${T.s4TracerHeading}</h4>
      ${tr.status === "loading" ? `<p class="glin-hint">${T.engineLoading}</p>` : bars([
        [T.barA, tr.nox.a, ""], [T.barB, tr.nox.b, ""], [T.barSum, tr.nox.a + tr.nox.b, "sum"],
        [tr.status === "ok" ? T.barEngineBoth : T.barSum, tr.status === "ok" ? tr.nox.both : tr.nox.a + tr.nox.b, "model"], [T.barYou, p.tracer, "you"]], "ppb")}
      <h4>${T.s4O3Heading}</h4>
      ${warnO3()}
      ${bars([[T.barA, c.a, ""], [T.barB, c.b, ""], [T.barSum, c.sum, "sum"], [T.barChemBoth, c.both, "model"], [T.barYou, p.o3, "you"]], "ppb")}
      ${T.s4Prompts.map((q) => `<p class="glin-prompt">${esc(q)}</p>`).join("")}
      ${doneNames.length ? `<p class="glin-hint">${esc(T.doneSettings(doneNames.join(", ")))}</p>` : ""}
      <label class="glin-field"><span>${T.s4NoteLabel}</span><textarea data-k="note" rows="3"></textarea></label>
      <p><button type="button" class="glin-btn" data-act="save-note">${T.s4NoteSave}</button> <span class="glin-hint" data-k="note-status"></span></p>
      ${nav(3, 5)}`;
  }

  function step5(): string {
    const b = exBase();
    return `<h3 tabindex="-1">${T.s5Heading}</h3>
      <p>${esc(T.s5Intro)}</p>
      ${warnO3()}
      <label class="glin-field"><span>${T.hourLabel}</span>
        <select data-k="scenario">${scenarioIds.map((id) => `<option value="${id}" ${id === S.scenario ? "selected" : ""}>${esc(hourLabel(id))}</option>`).join("")}</select></label>
      <div class="glin-row2">
        <label class="glin-field"><span>${T.s5Base}: NOx (ppb)</span><input type="number" min="0" max="${NOX_MAX}" step="1" data-k="ex-nox" value="${b.nox.toFixed(0)}"></label>
        <label class="glin-field"><span>${T.s5Base}: VOC (ppbC)</span><input type="number" min="0" max="${VOC_MAX}" step="10" data-k="ex-voc" value="${b.voc.toFixed(0)}"></label>
      </div>
      <label class="glin-field"><span>${T.s5AddA}: <output data-k="ex-a-out">${S.ex.addANox.toFixed(0)}</output></span><input type="range" min="0" max="60" step="1" data-k="ex-a" value="${S.ex.addANox}"></label>
      <label class="glin-field"><span>${T.s5AddB}: <output data-k="ex-b-out">${S.ex.addBVoc.toFixed(0)}</output></span><input type="range" min="0" max="450" step="10" data-k="ex-b" value="${S.ex.addBVoc}"></label>
      <label class="glin-field"><span>${T.s5Mult}: <output data-k="ex-m-out">${S.ex.mult.toFixed(1)}</output></span><input type="range" min="0.5" max="3" step="0.5" data-k="ex-m" value="${S.ex.mult}"></label>
      <label class="glin-check"><input type="checkbox" data-k="ex-ridge" ${S.ex.ridge ? "checked" : ""}> ${T.s5Ridge}</label>
      <div data-k="ex-readout"></div>
      <p><button type="button" class="glin-btn" data-act="pin">${T.s5Pin}</button> <button type="button" class="glin-btn" data-act="reset">${T.s5Reset}</button></p>
      <div data-k="ex-pins"></div>
      ${nav(4, 6, T.nav.next, lockText(6) !== "")}
      ${lockText(6) ? `<p class="glin-hint">${esc(lockText(6))}</p>` : ""}`;
  }

  function exploreReadout() {
    const out = main.querySelector('[data-k="ex-readout"]');
    if (!out) return;
    const c = combine(data, S.scenario, exBase(), exAddA(), exAddB());
    const m = S.ex.mult;
    const cm = combine(data, S.scenario, exBase(), scaled(exAddA(), m), scaled(exAddB(), m));
    out.innerHTML = `<div class="glin-cards">
        <div class="glin-card"><div class="lbl">${T.s2O3None}</div><div class="val">${c.base.toFixed(1)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.barA}</div><div class="val">${signed(c.a)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.barB}</div><div class="val">${signed(c.b)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.barSum}</div><div class="val">${signed(c.sum)} ppb</div></div>
        <div class="glin-card"><div class="lbl">${T.barChemBoth}</div><div class="val">${signed(c.both)} ppb</div></div>
      </div>
      ${m !== 1 ? `<p class="glin-hint">${esc(T.s5MultNote(m.toFixed(1), signed(cm.both), signed(m * c.both)))}</p>` : ""}
      ${c.clamped || cm.clamped ? `<p class="glin-hint">${T.s5Clamped}</p>` : ""}`;
    const pins = main.querySelector('[data-k="ex-pins"]');
    if (pins) {
      pins.innerHTML = S.ex.pins.length ? `<h4>${T.s5Pinned}</h4><ol class="glin-pins">${S.ex.pins.map((p, i) =>
        `<li>${esc(hourLabel(p.scenario))}: NOx ${p.base.nox.toFixed(0)} ppb, VOC ${p.base.voc.toFixed(0)} ppbC; A ${signed(p.c.a)}, B ${signed(p.c.b)}, sum ${signed(p.c.sum)}, both ${signed(p.c.both)} ppb <button type="button" class="glin-btn small" data-unpin="${i}" aria-label="Remove marked point ${i + 1}">Remove</button></li>`).join("")}</ol>` : "";
      pins.querySelectorAll<HTMLButtonElement>("[data-unpin]").forEach((b) => b.onclick = () => {
        const index = +b.dataset.unpin!;
        S.ex.pins.splice(index, 1);
        rec({ step: "explore-unpin", observed: { index } });
        exploreReadout(); drawIso();
      });
    }
  }

  function step6(): string {
    return `<h3 tabindex="-1">${T.s6Heading}</h3>
      <p>${esc(T.s6Intro)}</p>
      ${warnNo2()}
      <fieldset class="glin-choice inline"><legend>${T.s6PredictLabel}</legend>
        ${T.s6Choices.map(([k, t]) => `<label class="${S.no2.choice === k ? "on" : ""}"><input type="radio" name="glin-no2" value="${k}" ${S.no2.choice === k ? "checked" : ""} ${S.no2.revealed ? "disabled" : ""}> ${t}</label>`).join("")}
      </fieldset>
      <label class="glin-field"><span>${T.s6FactorLabel}</span><input type="number" min="0" step="0.1" data-k="no2-factor" value="${esc(S.no2.factor)}" ${S.no2.revealed ? "disabled" : ""}></label>
      ${S.no2.revealed && no2CanReveal(S.no2.choice, gate())
        ? `<p class="glin-result">${esc(T.s6Result)}</p>${T.s6Prompts.map((q) => `<p class="glin-prompt">${esc(q)}</p>`).join("")}<p class="glin-hint">${esc(T.s6Source)}</p>`
        : `<p><button type="button" class="glin-btn primary" data-act="no2-reveal" ${S.no2.choice ? "" : "disabled"}>${T.s6Reveal}</button></p>`}
      ${nav(5, null)}`;
  }

  // ---- instructor panel: notes and outcome table exist only when the host says the instructor
  // view is on; they live in a separate chunk that is not loaded otherwise.
  let instrToken = 0;
  function renderInstructor() {
    const token = ++instrToken;
    if (ctx.instructor !== true) { instr.innerHTML = ""; return; }
    import("./instructor").then(({ instructorPanelHtml }) => {
      if (token !== instrToken || ctx.instructor !== true) return;
      const rows = scenarioIds.flatMap((sid) => settingKeys.map((k) => {
        const c = fixedCombo(sid, k);
        return [hourLabel(sid), mod.settings[k].label, c.base.toFixed(1), signed(c.a), signed(c.b), signed(c.sum), signed(c.both), signed(c.interaction)];
      }));
      instr.innerHTML = instructorPanelHtml(rows, data.content_sha256.slice(0, 12));
    }).catch(() => { instr.innerHTML = ""; });
  }

  // ---- main render and event wiring
  function render() {
    renderSteps();
    const html = [step1, step2, step3, step4, step5, step6][S.step - 1]();
    main.innerHTML = html;
    wire();
    const showFig = (S.step === 4 && unlocked()) || S.step === 5;
    fig.hidden = !showFig;
    placeholder.hidden = showFig || S.step === 6;
    if (showFig) drawIso();
    if (S.step === 5) exploreReadout();
    renderInstructor();
  }

  function wire() {
    main.querySelectorAll<HTMLButtonElement>("[data-go]").forEach((b) => { b.onclick = () => go(Number(b.dataset.go)); });
    const q = <E extends Element>(s: string) => main.querySelector<E>(s);
    const sel = q<HTMLSelectElement>('select[data-k="scenario"]');
    if (sel) sel.onchange = () => { S.scenario = sel.value; S.ex.base = null; S.draft = { tracer: "", o3: "", expect: "", why: "", usedSum: false }; S.editing = false; render(); };
    main.querySelectorAll<HTMLInputElement>('input[name="glin-setting"]').forEach((r) => {
      r.onchange = () => { S.setting = r.value; S.ex.base = null; S.draft = { tracer: "", o3: "", expect: "", why: "", usedSum: false }; S.editing = false; render(); };
    });
    // step 3
    const tracer = q<HTMLInputElement>('input[data-k="tracer"]');
    const o3 = q<HTMLInputElement>('input[data-k="o3"]');
    const why = q<HTMLTextAreaElement>('textarea[data-k="why"]');
    const recBtn = q<HTMLButtonElement>('[data-act="record"]');
    const p = S.preds.get(key());
    if (why) why.value = p && !S.editing ? p.why : S.draft.why;
    const sync = () => {
      if (tracer) S.draft.tracer = tracer.value;
      if (o3) S.draft.o3 = o3.value;
      if (why) S.draft.why = why.value;
      if (recBtn) recBtn.disabled = !draftValid();
    };
    [tracer, o3, why].forEach((x) => { if (x) x.oninput = sync; });
    main.querySelectorAll<HTMLInputElement>('input[name="glin-expect"]').forEach((r) => {
      r.onchange = () => { sync(); S.draft.expect = r.value; main.querySelectorAll('input[name="glin-expect"]').forEach((x) => x.parentElement?.classList.toggle("on", (x as HTMLInputElement).checked)); };
    });
    const useSum = q<HTMLButtonElement>('[data-act="use-sum"]');
    if (useSum && o3) useSum.onclick = () => { o3.value = fixedCombo().sum.toFixed(1); S.draft.usedSum = true; sync(); o3.focus(); };
    if (recBtn) recBtn.onclick = () => {
      sync();
      if (!draftValid()) return;
      const pred: Prediction = { tracer: Number(S.draft.tracer), o3: Number(S.draft.o3), expect: S.draft.expect, why: S.draft.why, usedSum: S.draft.usedSum };
      S.preds.set(key(), pred);
      S.editing = false;
      const c = fixedCombo();
      rec({ step: "predict", prediction: {
        scenario: S.scenario, setting: S.setting, tracer_nox_ppb: pred.tracer, o3_change_ppb: pred.o3, expectation: pred.expect || null,
        reason: pred.why, used_sum_button: pred.usedSum, sum_shown_ppb: round2(c.sum), table: data.content_sha256.slice(0, 12) } });
      revealRecord();
      go(4);
    };
    const edit = q<HTMLButtonElement>('[data-act="edit"]');
    if (edit) edit.onclick = () => {
      const old = S.preds.get(key());
      if (old) S.draft = { tracer: String(old.tracer), o3: String(old.o3), expect: old.expect, why: old.why, usedSum: old.usedSum };
      S.editing = true;
      S.preds.delete(key());
      render();
    };
    // step 4
    const note = q<HTMLTextAreaElement>('textarea[data-k="note"]');
    if (note) { note.value = S.notes.get(key()) ?? ""; note.oninput = () => { S.notes.set(key(), note.value); }; }
    const saveNote = q<HTMLButtonElement>('[data-act="save-note"]');
    if (saveNote) saveNote.onclick = () => {
      const text = S.notes.get(key()) ?? "";
      if (!text.trim()) return;
      rec({ step: "note", observed: { scenario: S.scenario, setting: S.setting, text } });
      const st = q<HTMLElement>('[data-k="note-status"]');
      if (st) st.textContent = T.s4NoteSaved;
    };
    // step 5
    const exN = q<HTMLInputElement>('input[data-k="ex-nox"]');
    const exV = q<HTMLInputElement>('input[data-k="ex-voc"]');
    const onBase = () => {
      const n = clamp(Number(exN?.value), 0, NOX_MAX);
      const v = clamp(Number(exV?.value), 0, VOC_MAX);
      if (Number.isFinite(n) && Number.isFinite(v)) { S.ex.base = { nox: n, voc: v }; exploreReadout(); drawIso(); }
    };
    if (exN) exN.oninput = onBase;
    if (exV) exV.oninput = onBase;
    const slider = (k: string, set: (v: number) => void, digits: number) => {
      const s = q<HTMLInputElement>(`input[data-k="${k}"]`);
      const o = q<HTMLOutputElement>(`output[data-k="${k}-out"]`);
      if (s) s.oninput = () => { set(Number(s.value)); if (o) o.textContent = Number(s.value).toFixed(digits); exploreReadout(); drawIso(); };
    };
    slider("ex-a", (v) => { S.ex.addANox = v; }, 0);
    slider("ex-b", (v) => { S.ex.addBVoc = v; }, 0);
    slider("ex-m", (v) => { S.ex.mult = v; }, 1);
    const ridge = q<HTMLInputElement>('input[data-k="ex-ridge"]');
    if (ridge) ridge.onchange = () => { S.ex.ridge = ridge.checked; drawIso(); };
    const pin = q<HTMLButtonElement>('[data-act="pin"]');
    if (pin) pin.onclick = pinPoint;
    const reset = q<HTMLButtonElement>('[data-act="reset"]');
    if (reset) reset.onclick = () => { S.ex.base = null; S.ex.addANox = A.add_nox_ppb; S.ex.addBVoc = B.add_voc_ppbC; S.ex.mult = 1; render(); };
    // step 6
    main.querySelectorAll<HTMLInputElement>('input[name="glin-no2"]').forEach((r) => {
      r.onchange = () => {
        S.no2.choice = r.value;
        main.querySelectorAll('input[name="glin-no2"]').forEach((x) => x.parentElement?.classList.toggle("on", (x as HTMLInputElement).checked));
        const b = q<HTMLButtonElement>('[data-act="no2-reveal"]'); if (b) b.disabled = false;
      };
    });
    const fac = q<HTMLInputElement>('input[data-k="no2-factor"]');
    if (fac) fac.oninput = () => { S.no2.factor = fac.value; };
    const rev = q<HTMLButtonElement>('[data-act="no2-reveal"]');
    if (rev) rev.onclick = () => {
      if (!no2CanReveal(S.no2.choice, gate())) return;
      rec({ step: "no2-predict", prediction: { choice: S.no2.choice, factor: S.no2.factor === "" ? null : Number(S.no2.factor) } });
      S.no2.revealed = true;
      rec({ step: "no2-reveal", observed: { source: "phase2_D", max_ratio: { OLM: 4.5, ARM2: 1.8, PVMRM: 5.8 }, max_ratio_philadelphia: { OLM: 4.1, ARM2: 1.8, PVMRM: 6.4 } } });
      render();
    };
  }

  function revealRecord() {
    const k = key();
    if (S.compared.has(k)) return;
    S.compared.add(k);
    const c = fixedCombo();
    const tr = S.tracer.get(S.scenario);
    rec({ step: "compare", observed: {
      scenario: S.scenario, setting: S.setting,
      o3: { base: round2(c.base), a: round2(c.a), b: round2(c.b), sum: round2(c.sum), both: round2(c.both) },
      tracer_nox_ppb: tr && tr.status === "ok" ? { a: round2(tr.nox.a), b: round2(tr.nox.b), both: round2(tr.nox.both) } : null,
      table: data.content_sha256.slice(0, 12) } });
    renderSteps();
  }

  function pinPoint() {
    const c = combine(data, S.scenario, exBase(), exAddA(), exAddB());
    const p: Pin = { scenario: S.scenario, base: { ...exBase() }, addA: exAddA(), addB: exAddB(), c };
    S.ex.pins.push(p);
    rec({ step: "explore-pin", observed: {
      scenario: p.scenario, nox_ppb: round2(p.base.nox), voc_ppbC: round2(p.base.voc), add_a: p.addA, add_b: p.addB, mult: S.ex.mult,
      o3: { base: round2(c.base), a: round2(c.a), b: round2(c.b), sum: round2(c.sum), both: round2(c.both) } } });
    exploreReadout();
    drawIso();
  }

  // ---- isopleth canvas
  const gridCache = new Map<string, { g: number[][]; nv: number; nn: number; levels: number[] }>();
  const M = { l: 50, r: 30, t: 12, b: 40 };
  let W = 420;
  let H = 380;
  const xs = (v: number) => M.l + (v / VOC_MAX) * (W - M.l - M.r);
  const ys = (n: number) => H - M.b - (n / NOX_MAX) * (H - M.t - M.b);

  function surface(sid: string) {
    let s = gridCache.get(sid);
    if (!s) {
      const nv = 120;
      const nn = 96;
      const g = sampleGrid(data, sid, VOC_MAX, NOX_MAX, nv, nn);
      let lo = Infinity;
      let hi = -Infinity;
      for (const row of g) for (const v of row) { lo = Math.min(lo, v); hi = Math.max(hi, v); }
      const step = hi - lo > 40 ? 5 : hi - lo > 15 ? 2 : 1;
      const levels: number[] = [];
      for (let L = Math.ceil(lo / step) * step; L <= hi; L += step) if (L > lo) levels.push(L);
      s = { g, nv, nn, levels };
      gridCache.set(sid, s);
    }
    return s;
  }

  function drawIso() {
    if (fig.hidden) return;
    const c2 = canvas.getContext("2d");
    if (!c2) return;
    const dpr = window.devicePixelRatio || 1;
    W = Math.max(280, canvas.clientWidth || 420);
    H = Math.round(W * 0.9);
    canvas.width = Math.round(W * dpr);
    canvas.height = Math.round(H * dpr);
    canvas.style.height = `${H}px`;
    c2.setTransform(dpr, 0, 0, dpr, 0, 0);
    const css = getComputedStyle(host);
    const ink = css.getPropertyValue("--ink").trim() || "#1e1e1e";
    const muted = css.getPropertyValue("--muted").trim() || "#595954";
    const accent = css.getPropertyValue("--accent").trim() || "#1f55a8";
    const amber = css.getPropertyValue("--amber").trim() || "#8a4b00";
    c2.fillStyle = css.getPropertyValue("--panel").trim() || "#fff";
    c2.fillRect(0, 0, W, H);
    const s = surface(S.scenario);
    const gx = (c: number) => xs((c / s.nv) * VOC_MAX);
    const gy = (r: number) => ys((r / s.nn) * NOX_MAX);
    c2.lineWidth = 1;
    c2.font = "10px system-ui, sans-serif";
    const placed: [number, number][] = [];
    for (const L of s.levels) {
      const segs = contourSegments(s.g, L);
      c2.strokeStyle = "#8a8a84";
      c2.beginPath();
      let best: [number, number] | null = null;
      let bestD = Infinity;
      for (const [x1, y1, x2, y2] of segs) {
        c2.moveTo(gx(x1), gy(y1));
        c2.lineTo(gx(x2), gy(y2));
        // Label where the contour meets the diagonal NOx = VOC / 8 (in data units), away from the frame.
        const voc = (x1 / s.nv) * VOC_MAX;
        const nox = (y1 / s.nn) * NOX_MAX;
        const d = Math.abs(nox - voc / 8) + (x1 > s.nv * 0.95 || y1 > s.nn * 0.95 ? 1e3 : 0);
        if (d < bestD) { bestD = d; best = [gx(x1), gy(y1)]; }
      }
      c2.stroke();
      if (best && !placed.some(([px, py]) => Math.hypot(px - best![0], py - best![1]) < 16)) {
        placed.push(best);
        c2.fillStyle = muted; c2.textAlign = "left"; c2.textBaseline = "bottom"; c2.fillText(String(L), best[0] + 2, best[1] - 1);
      }
    }
    if (S.ex.ridge) {
      c2.strokeStyle = ink; c2.setLineDash([5, 4]); c2.beginPath();
      ridgeLine(data, S.scenario).filter((m) => m.voc <= VOC_MAX && m.nox <= NOX_MAX).forEach((m, i) => (i ? c2.lineTo(xs(m.voc), ys(m.nox)) : c2.moveTo(xs(m.voc), ys(m.nox))));
      c2.stroke(); c2.setLineDash([]);
    }
    // axes
    c2.strokeStyle = muted; c2.strokeRect(M.l, M.t, W - M.l - M.r, H - M.t - M.b);
    c2.fillStyle = ink; c2.textAlign = "center"; c2.textBaseline = "top";
    for (let v = 0; v <= VOC_MAX; v += 200) c2.fillText(String(v), xs(v), H - M.b + 4);
    c2.fillText(T.axisVoc, (M.l + W - M.r) / 2, H - 16);
    c2.textAlign = "right"; c2.textBaseline = "middle";
    for (let n = 0; n <= NOX_MAX; n += 20) c2.fillText(String(n), M.l - 4, ys(n));
    c2.save(); c2.translate(12, (M.t + H - M.b) / 2); c2.rotate(-Math.PI / 2); c2.textAlign = "center"; c2.fillText(T.axisNox, 0, 0); c2.restore();
    // settings and points
    for (const k of settingKeys) {
      const m = settingMix(k);
      c2.strokeStyle = muted; c2.lineWidth = 1; c2.beginPath(); c2.arc(xs(m.voc), ys(m.nox), 4, 0, 7); c2.stroke();
      c2.fillStyle = muted; c2.textAlign = "left"; c2.textBaseline = "top"; c2.fillText(k, xs(m.voc) + 5, ys(m.nox) + 3);
    }
    const explore = S.step === 5;
    const base = explore ? exBase() : settingMix();
    const aA = explore ? scaled(exAddA(), S.ex.mult) : addOf(A);
    const aB = explore ? scaled(exAddB(), S.ex.mult) : addOf(B);
    const pa = { nox: base.nox + aA.nox, voc: base.voc + aA.voc };
    const pb = { nox: base.nox + aB.nox, voc: base.voc + aB.voc };
    const pab = { nox: base.nox + aA.nox + aB.nox, voc: base.voc + aA.voc + aB.voc };
    arrow(c2, base, pa, accent, []);
    arrow(c2, base, pb, amber, [5, 3]);
    arrow(c2, base, pab, ink, [2, 3]);
    dot(c2, base, "", ink, 4.5);
    dot(c2, pa, "A", accent, 3.5);
    dot(c2, pb, "B", amber, 3.5);
    dot(c2, pab, "A+B", ink, 3.5);
    S.ex.pins.filter((p) => p.scenario === S.scenario).forEach((p, i) => {
      const x = xs(p.base.voc); const y = ys(p.base.nox);
      c2.strokeStyle = ink; c2.lineWidth = 1.5; c2.beginPath(); c2.moveTo(x - 4, y - 4); c2.lineTo(x + 4, y + 4); c2.moveTo(x - 4, y + 4); c2.lineTo(x + 4, y - 4); c2.stroke();
      c2.fillStyle = ink; c2.textAlign = "left"; c2.textBaseline = "bottom"; c2.fillText(String(i + 1), x + 5, y - 3);
    });
    canvas.setAttribute("aria-label", T.canvasLabel(hourLabel(S.scenario)));
    hint.textContent = isDay() ? T.isoHintDay : T.isoHintDark;
  }

  function arrow(c2: CanvasRenderingContext2D, f: Mixture, t: Mixture, col: string, dash: number[]) {
    const x1 = xs(f.voc); const y1 = ys(f.nox); const x2 = xs(t.voc); const y2 = ys(t.nox);
    if (Math.hypot(x2 - x1, y2 - y1) < 2) return;
    c2.strokeStyle = col; c2.fillStyle = col; c2.lineWidth = 2; c2.setLineDash(dash);
    c2.beginPath(); c2.moveTo(x1, y1); c2.lineTo(x2, y2); c2.stroke(); c2.setLineDash([]);
    const an = Math.atan2(y2 - y1, x2 - x1);
    c2.beginPath(); c2.moveTo(x2, y2); c2.lineTo(x2 - 8 * Math.cos(an - 0.4), y2 - 8 * Math.sin(an - 0.4)); c2.lineTo(x2 - 8 * Math.cos(an + 0.4), y2 - 8 * Math.sin(an + 0.4)); c2.closePath(); c2.fill();
  }

  function dot(c2: CanvasRenderingContext2D, q: Mixture, t: string, col: string, r: number) {
    c2.fillStyle = col; c2.beginPath(); c2.arc(xs(q.voc), ys(q.nox), r, 0, 7); c2.fill();
    if (t) { c2.font = "bold 10.5px system-ui, sans-serif"; c2.textAlign = "left"; c2.textBaseline = "bottom"; c2.fillText(t, xs(q.voc) + 6, ys(q.nox) - 3); c2.font = "10px system-ui, sans-serif"; }
  }

  canvas.addEventListener("click", (e) => {
    if (S.step !== 5) return;
    const r = canvas.getBoundingClientRect();
    const voc = ((e.clientX - r.left - M.l) / (W - M.l - M.r)) * VOC_MAX;
    const nox = ((H - M.b - (e.clientY - r.top)) / (H - M.t - M.b)) * NOX_MAX;
    if (voc < 0 || nox < 0 || voc > VOC_MAX || nox > NOX_MAX) return;
    setBase({ nox: Math.round(nox), voc: Math.round(voc / 5) * 5 });
  });
  canvas.addEventListener("keydown", (e) => {
    if (S.step !== 5) return;
    const b = exBase();
    const big = e.shiftKey;
    const dn = big ? 5 : 1;
    const dv = big ? 50 : 10;
    let next: Mixture | null = null;
    if (e.key === "ArrowUp") next = { nox: b.nox + dn, voc: b.voc };
    else if (e.key === "ArrowDown") next = { nox: b.nox - dn, voc: b.voc };
    else if (e.key === "ArrowRight") next = { nox: b.nox, voc: b.voc + dv };
    else if (e.key === "ArrowLeft") next = { nox: b.nox, voc: b.voc - dv };
    else if (e.key === "Enter") { e.preventDefault(); pinPoint(); return; }
    if (next) { e.preventDefault(); setBase({ nox: clamp(next.nox, 0, NOX_MAX), voc: clamp(next.voc, 0, VOC_MAX) }); }
  });

  function setBase(m: Mixture) {
    S.ex.base = m;
    const n = main.querySelector<HTMLInputElement>('input[data-k="ex-nox"]');
    const v = main.querySelector<HTMLInputElement>('input[data-k="ex-voc"]');
    if (n) n.value = m.nox.toFixed(0);
    if (v) v.value = m.voc.toFixed(0);
    exploreReadout();
    drawIso();
  }

  const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(() => drawIso()) : null;
  ro?.observe(fig);

  render();

  return () => {
    ro?.disconnect();
    root.innerHTML = "";
  };
}

// ---- small helpers
function el(tag: string, cls: string): HTMLElement {
  const e = document.createElement(tag);
  e.className = cls;
  return e;
}

function esc(s: string): string {
  return s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;");
}

function clamp(v: number, lo: number, hi: number): number {
  return Math.min(hi, Math.max(lo, v));
}

function round2(v: number): number {
  return Math.round(v * 100) / 100;
}

export { lookup };
